BEGIN;
INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data,aud,role,encrypted_password,email_confirmed_at,created_at,updated_at)SELECT('fc510000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid,'notebook-'||x||'@fixture.invalid','{"full_name":"Notebook synthetic","account_type_request":"EXTERNAL"}','{}','authenticated','authenticated','no-password',now(),now(),now()FROM generate_series(1,3)x;
