INSERT INTO cbgpu_schools.gpu_resources(id,node_id,hardware_uuid,gpu_index,name,memory_total_mib,last_seen_at,reported_sequence,credential_version)VALUES('fc540000-0000-4000-8000-000000000001','fc530000-0000-4000-8000-000000000001','GPU-aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',0,'FakeGPU',1000,clock_timestamp(),1,1);
INSERT INTO cbgpu_schools.gpu_resource_reservations(id,resource_id,owner_id,starts_at,ends_at)VALUES('fc550000-0000-4000-8000-000000000001','fc540000-0000-4000-8000-000000000001','fc510000-0000-4000-8000-000000000001',now()-interval'1minute',now()+interval'1hour');
CREATE TEMP TABLE nb(k text PRIMARY KEY,v jsonb);GRANT ALL ON nb TO authenticated,service_role;
SELECT set_config('request.jwt.claims','{"sub":"fc510000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fc520000-0000-4000-8000-000000000001"}',true);SET LOCAL ROLE authenticated;
DO $$BEGIN BEGIN PERFORM public.school_gpu_notebook_api('fixture-notebook','launch','{"reservation_id":"fc550000-0000-4000-8000-000000000001","client_request_id":"fc560000-0000-4000-8000-000000000001","temporary_storage_consent":true}');RAISE EXCEPTION'DISABLED_EXECUTOR_STARTED';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END$$;
RESET ROLE;UPDATE cbgpu_schools.gpu_notebook_policy SET enabled=true,image_digest='registry.fixture/notebook@sha256:'||repeat('a',64);
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);SET LOCAL ROLE service_role;
SELECT public.school_gpu_notebook_device('fc530000-0000-4000-8000-000000000001',1,1,extract(epoch FROM now())::bigint,'capabilities',jsonb_build_object('executor_protocol',3,'image_digest','registry.fixture/notebook@sha256:'||repeat('a',64),'docker_ready',true,'toolkit_ready',true,'hardware_uuids',jsonb_build_array('GPU-aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa')));
SELECT public.school_gpu_notebook_relay('fc530000-0000-4000-8000-000000000001',1,true);
DO $$BEGIN BEGIN PERFORM public.school_gpu_notebook_device('fc530000-0000-4000-8000-000000000001',1,1,extract(epoch FROM now())::bigint,'claim','{}');RAISE EXCEPTION'REPLAY_ACCEPTED';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END$$;
RESET ROLE;SELECT set_config('request.jwt.claims','{"sub":"fc510000-0000-4000-8000-000000000003","role":"authenticated","session_id":"fc520000-0000-4000-8000-000000000003"}',true);SET LOCAL ROLE authenticated;
DO $$BEGIN BEGIN PERFORM public.school_gpu_notebook_api('fixture-notebook','status','{"reservation_id":"fc550000-0000-4000-8000-000000000001"}');RAISE EXCEPTION'FOREIGN_BOOKING_READ';EXCEPTION WHEN no_data_found THEN NULL;END;END$$;
RESET ROLE;SELECT set_config('request.jwt.claims','{"sub":"fc510000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fc520000-0000-4000-8000-000000000001"}',true);SET LOCAL ROLE authenticated;
INSERT INTO nb VALUES('job',public.school_gpu_notebook_api('fixture-notebook','launch','{"reservation_id":"fc550000-0000-4000-8000-000000000001","client_request_id":"fc560000-0000-4000-8000-000000000001","temporary_storage_consent":true}'));
DO $$DECLARE x jsonb;BEGIN x:=public.school_gpu_notebook_api('fixture-notebook','launch','{"reservation_id":"fc550000-0000-4000-8000-000000000001","client_request_id":"fc560000-0000-4000-8000-000000000001","temporary_storage_consent":true}');IF x<>(SELECT v FROM nb WHERE k='job')THEN RAISE EXCEPTION'IDEMPOTENT_LAUNCH_CHANGED';END IF;BEGIN PERFORM public.school_gpu_notebook_api('fixture-notebook','session','{"reservation_id":"fc550000-0000-4000-8000-000000000001"}');RAISE EXCEPTION'QUEUED_SESSION_MINTED';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END$$;
RESET ROLE;SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);SET LOCAL ROLE service_role;
INSERT INTO nb VALUES('claim',public.school_gpu_notebook_device('fc530000-0000-4000-8000-000000000001',1,2,extract(epoch FROM now())::bigint,'claim','{}'));
DO $$DECLARE x jsonb;BEGIN x:=public.school_gpu_notebook_device('fc530000-0000-4000-8000-000000000001',1,3,extract(epoch FROM now())::bigint,'claim','{}');IF x->'command'<>'null'::jsonb THEN RAISE EXCEPTION'DUPLICATE_LEASE';END IF;END$$;
INSERT INTO nb VALUES('result',jsonb_build_object('command_id',(SELECT v#>>'{command,command_id}'FROM nb WHERE k='claim'),'lease_epoch',1,'lease_token',(SELECT v#>>'{command,lease_token}'FROM nb WHERE k='claim'),'result',jsonb_build_object('state','RUNNING','job_id',(SELECT v#>>'{job,id}'FROM nb WHERE k='job'),'generation',(SELECT v#>>'{job,id}'FROM nb WHERE k='job'),'error_code',NULL)));
SELECT public.school_gpu_notebook_device('fc530000-0000-4000-8000-000000000001',1,4,extract(epoch FROM now())::bigint,'result',(SELECT v FROM nb WHERE k='result'));
SELECT public.school_gpu_notebook_device('fc530000-0000-4000-8000-000000000001',1,5,extract(epoch FROM now())::bigint,'result',(SELECT v FROM nb WHERE k='result'));
SELECT public.school_gpu_notebook_device('fc530000-0000-4000-8000-000000000001',1,6,extract(epoch FROM now())::bigint,'renew',(SELECT v-'result'FROM nb WHERE k='result'));
RESET ROLE;SELECT set_config('request.jwt.claims','{"sub":"fc510000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fc520000-0000-4000-8000-000000000001"}',true);SET LOCAL ROLE authenticated;
INSERT INTO nb VALUES('session',public.school_gpu_notebook_owner_session((SELECT(v#>>'{job,id}')::uuid FROM nb WHERE k='job')));
SELECT set_config('request.jwt.claims','{"sub":"fc510000-0000-4000-8000-000000000003","role":"authenticated","session_id":"fc520000-0000-4000-8000-000000000003"}',true);
DO $$BEGIN BEGIN PERFORM public.school_gpu_notebook_owner_session((SELECT(v#>>'{job,id}')::uuid FROM nb WHERE k='job'));RAISE EXCEPTION'FOREIGN_JOB_BOOTSTRAP';EXCEPTION WHEN no_data_found THEN NULL;END;END$$;
SELECT set_config('request.jwt.claims','{"sub":"fc510000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fc520000-0000-4000-8000-000000000001"}',true);
DO $$BEGIN IF(SELECT(v->>'expires_at')::timestamptz FROM nb WHERE k='session')<now()+interval'59 minutes'OR(SELECT(v->>'expires_at')::timestamptz FROM nb WHERE k='session')>now()+interval'1hour'THEN RAISE EXCEPTION'COOKIE_NOT_BOUND_TO_BOOKING';END IF;END$$;
RESET ROLE;SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);SET LOCAL ROLE service_role;
DO $$DECLARE x jsonb;BEGIN x:=public.school_gpu_notebook_session((SELECT v->>'cookie_token'FROM nb WHERE k='session'),(SELECT(v#>>'{job,id}')::uuid FROM nb WHERE k='job'));IF x->>'valid'<>'true'THEN RAISE EXCEPTION'OWN_SESSION_DENIED';END IF;x:=public.school_gpu_notebook_session((SELECT v->>'cookie_token'FROM nb WHERE k='session'),gen_random_uuid());IF x->>'valid'<>'false'THEN RAISE EXCEPTION'CROSS_JOB_COOKIE';END IF;END$$;
RESET ROLE;UPDATE cbgpu_schools.gpu_notebook_commands SET lease_expires_at=now()-interval'1second'WHERE kind='START_NOTEBOOK';SET LOCAL ROLE service_role;
DO $$BEGIN IF public.school_gpu_notebook_session((SELECT v->>'cookie_token'FROM nb WHERE k='session'),(SELECT(v#>>'{job,id}')::uuid FROM nb WHERE k='job'))->>'valid'<>'false'THEN RAISE EXCEPTION'EXPIRED_RUNTIME_LEASE_ACCESS';END IF;END$$;
RESET ROLE;UPDATE cbgpu_schools.gpu_notebook_commands SET lease_expires_at=now()+interval'45seconds'WHERE kind='START_NOTEBOOK';SET LOCAL ROLE service_role;
SELECT public.school_gpu_notebook_relay('fc530000-0000-4000-8000-000000000001',1,false);
DO $$BEGIN IF public.school_gpu_notebook_session((SELECT v->>'cookie_token'FROM nb WHERE k='session'),(SELECT(v#>>'{job,id}')::uuid FROM nb WHERE k='job'))->>'valid'<>'false'THEN RAISE EXCEPTION'DISCONNECTED_RELAY_ACCESS';END IF;END$$;
SELECT public.school_gpu_notebook_relay('fc530000-0000-4000-8000-000000000001',1,true);
RESET ROLE;UPDATE auth.sessions SET not_after=now()-interval'1second'WHERE id='fc520000-0000-4000-8000-000000000001';SET LOCAL ROLE service_role;
DO $$BEGIN IF public.school_gpu_notebook_session((SELECT v->>'cookie_token'FROM nb WHERE k='session'),(SELECT(v#>>'{job,id}')::uuid FROM nb WHERE k='job'))->>'valid'<>'false'THEN RAISE EXCEPTION'REVOKED_SESSION_ALLOWED';END IF;END$$;
RESET ROLE;UPDATE auth.sessions SET not_after=NULL WHERE id='fc520000-0000-4000-8000-000000000001';UPDATE cbgpu_schools.memberships SET status='SUSPENDED',verified=false WHERE user_id='fc510000-0000-4000-8000-000000000001';SET LOCAL ROLE service_role;
DO $$BEGIN IF public.school_gpu_notebook_session((SELECT v->>'cookie_token'FROM nb WHERE k='session'),(SELECT(v#>>'{job,id}')::uuid FROM nb WHERE k='job'))->>'valid'<>'false'THEN RAISE EXCEPTION'REVOKED_MEMBERSHIP_ALLOWED';END IF;END$$;
INSERT INTO nb VALUES('stop',public.school_gpu_notebook_device('fc530000-0000-4000-8000-000000000001',1,7,extract(epoch FROM now())::bigint,'claim','{}'));
DO $$BEGIN IF(SELECT v#>>'{command,kind}'FROM nb WHERE k='stop')<>'STOP_NOTEBOOK'THEN RAISE EXCEPTION'REVOKE_DID_NOT_STOP';END IF;END$$;
RESET ROLE;
DO $$BEGIN IF(SELECT status FROM cbgpu_schools.gpu_notebook_jobs WHERE reservation_id='fc550000-0000-4000-8000-000000000001')<>'STOPPING'THEN RAISE EXCEPTION'LEASE_TIMEOUT_FREED_RUNTIME';END IF;END$$;
RESET ROLE;
INSERT INTO cbgpu_accounts.guest_requests(external_user_id,requester_id,school_id,project_name,purpose,resources,starts_at,ends_at,status)VALUES('fc510000-0000-4000-8000-000000000003','fc510000-0000-4000-8000-000000000002','fixture-notebook','Guest notebook','Synthetic only',array['gpu'],now()-interval'1hour',now()+interval'2hours','APPROVED');
DO $$BEGIN IF NOT cbgpu_schools.gpu_notebook_permission('fc510000-0000-4000-8000-000000000003','fixture-notebook',now(),now()+interval'1hour')THEN RAISE EXCEPTION'EXPLICIT_GUEST_DENIED';END IF;IF cbgpu_schools.gpu_notebook_permission('fc510000-0000-4000-8000-000000000003','fixture-notebook',now(),now()+interval'3hours')THEN RAISE EXCEPTION'GUEST_INTERVAL_EXCEEDED';END IF;END$$;
INSERT INTO cbgpu_schools.memberships(user_id,school_id,membership_type,status,verified,school_roles)VALUES('fc510000-0000-4000-8000-000000000003','fixture-notebook','STUDENT','REVERIFICATION_REQUIRED',false,'{}');
DO $$BEGIN IF cbgpu_schools.gpu_notebook_permission('fc510000-0000-4000-8000-000000000003','fixture-notebook',now(),now()+interval'1hour')THEN RAISE EXCEPTION'REVERIFY_GUEST_BYPASS';END IF;END$$;
DELETE FROM cbgpu_schools.memberships WHERE user_id='fc510000-0000-4000-8000-000000000003';UPDATE cbgpu_schools.memberships SET status='SUSPENDED',verified=false WHERE user_id='fc510000-0000-4000-8000-000000000002';
DO $$BEGIN IF cbgpu_schools.gpu_notebook_permission('fc510000-0000-4000-8000-000000000003','fixture-notebook',now(),now()+interval'1hour')THEN RAISE EXCEPTION'REVOKED_SPONSOR_GUEST';END IF;END$$;
ROLLBACK;
